    for id, c in pairs(cs) do
        if type(c) == "table" and c.unlocked and id ~= M.city() and not F.done[id] then pick = id break end
    end
    if not pick then F.wait("move", 60) return end
    local ok = F.try("move", "setCity", pick)
    if ok then notify(__T["Moved to "] .. tostring(pick)) LOG("move", pick) F.wait("build", 4) F.wait("move", 60) end
end
function F.tier()
    local s = M.state()
    local cs = s and s.cities
    if type(cs) ~= "table" then F.wait("tier", 30) return end
    local limit = val("f_tierpay", 30) * 60
    local cur = M.city()
    local best, bv
    for id, c in pairs(cs) do
        local t = type(c) == "table" and c.unlocked and c.tier
        if type(t) == "table" and t.next and M.num(t.gain) > 0 and M.num(t.cost) > 0 then
            local pb = M.num(t.cost) / M.num(t.gain)
            local keep = c.pay == M.country() and M.parse(val("u_keep", "0")) or 0
            local wal = c.pay == M.country() and M.wallet() or M.wallet(c.pay)
            local building = id == cur and not F.cityDone(id)
            if pb <= limit and not building and M.num(t.cost) <= wal - keep and (not bv or pb < bv) then best, bv = id, pb end
        end
    end
    if not best then F.wait("tier", 20) return end
    local ok = F.try("tier", "cityTier", best)
    if ok then LOG("tier", best, math.floor(bv)) end
end
