    Menu:AddDropdown("ui_scale", { Text = __T["UI Scale"], Values = { "60%", "75%", "90%", "100%", "110%", "125%" }, Default = Library.IsMobile and "75%" or "100%", Callback = function(v) pcall(function() Library:SetDPIScale(tonumber((v:gsub("%%", "")))) end) end })
    if Library.IsMobile then pcall(function() Library:SetDPIScale(75) end) end
    Menu:AddToggle("ui_quiet", { Text = __T["Quiet Hub Popups"], Default = false })
    Menu:AddButton({ Text = __T["Unload"], Func = function() pcall(_G.__CW_MT_CLEAN) end })
    SaveManager:SetLibrary(Library)
    ThemeManager:SetLibrary(Library)
